// topik: BE4001/XX/DATA, isi: "SM,AM,AT"
const kel = msg.topic.split('/')[1];
const nilai = String(msg.payload).split(',').map(Number);
if (!/^\d{2}$/.test(kel) || nilai.length < 3 || nilai.slice(0, 3).some(isNaN)) {
    node.warn('data diabaikan: ' + msg.topic + ' = ' + msg.payload);
    return null;
}
msg.measurement = 'kel_' + kel + '_data';
msg.payload = [{ SM: nilai[0], AM: nilai[1], AT: nilai[2] }, { kelompok: kel }];
return msg;

// topik: BE4001/XX/PUMP, isi: "mode,pompa" (1,1 = otomatis dan pompa nyala)
const kel = msg.topic.split('/')[1];
const nilai = String(msg.payload).split(',').map(Number);
if (!/^\d{2}$/.test(kel) || nilai.length < 2 || nilai.slice(0, 2).some(isNaN)) {
    node.warn('status pompa diabaikan: ' + msg.topic + ' = ' + msg.payload);
    return null;
}
msg.measurement = 'kel_' + kel + '_pompa';
msg.payload = [{ mode: nilai[0], pompa: nilai[1] }, { kelompok: kel }];
return msg;
